/usr/local/Cellar/python@3.14/3.14.6/Frameworks/Python.framework/Versions/3.14/Resources/Python.app/Contents/MacOS/Python /Users/joshc/develop/dotfile-vnext/.venv/bin/ansible HOM-LAB-HVH-02 -i inventory/inventory.yaml -m ansible.windows.win_powershell -a {"error_action":"stop","script":"$Ansible.Changed = $false
$physical = @(Get-PhysicalDisk | ForEach-Object {
  $counter = Get-StorageReliabilityCounter -PhysicalDisk $_ -ErrorAction SilentlyContinue
  [PSCustomObject]@{
    FriendlyName = $_.FriendlyName
    SerialNumber = $_.SerialNumber
    MediaType = $_.MediaType.ToString()
    BusType = $_.BusType.ToString()
    HealthStatus = $_.HealthStatus.ToString()
    OperationalStatus = @($_.OperationalStatus | ForEach-Object { $_.ToString() })
    SizeGiB = [math]::Round($_.Size / 1GB, 1)
    TemperatureC = if ($counter) { $counter.Temperature } else { $null }
    Wear = if ($counter) { $counter.Wear } else { $null }
  }
})
$volumes = @(Get-Volume | Where-Object { $_.DriveLetter } | ForEach-Object {
  $partition = Get-Partition -DriveLetter $_.DriveLetter
  $disk = Get-Disk -Number $partition.DiskNumber
  [PSCustomObject]@{
    Drive = "$($_.DriveLetter):"
    DiskNumber = $disk.Number
    FriendlyName = $disk.FriendlyName
    SerialNumber = $disk.SerialNumber
    BusType = $disk.BusType.ToString()
    SizeGiB = [math]::Round($disk.Size / 1GB, 1)
    VolumeFreeGiB = [math]::Round($_.SizeRemaining / 1GB, 1)
    VolumeHealth = $_.HealthStatus.ToString()
  }
})
$attachments = @(Get-VMHardDiskDrive -VMName "hom-lab-ctl-k3s-02" |
  Select-Object ControllerType,ControllerNumber,ControllerLocation,Path)
$Ansible.Result = @{
  physical_disks = $physical
  volumes = $volumes
  k3s_attachments = $attachments
}"}

